"""Review 020 acceptance tests (Codex H-145 / H-147) against the hosted project, in throw-away scratch schemas:

* the old routes' script (``oracle_content.json``, generated by the OLD code) replayed on the new endpoints: every
  response and every ``GET /api/content`` identical, the seed imported through the archived document + the backfill;
* the upgrade: a schema migrated BEFORE 0011 with an imported two-item log and an extra key, then 0011: the whole
  GET equals the old one; an edit survives a second backfill;
* events: one per changing write; an unchanged edit, an unknown and a repeated delete write none;
* a deleted id named again starts fresh on top and keeps its history;
* two new items in the same second (sequential and concurrent) get distinct ids; a non-string id is refused.
"""

from __future__ import annotations

import json
import re
import secrets
import threading
from collections.abc import Iterator
from datetime import datetime
from pathlib import Path
from typing import Any

import pytest
from fastapi.testclient import TestClient
from psycopg.types.json import Jsonb

from projectzero.api.app import create_app
from projectzero.core.config import Settings
from projectzero.core.db import connect, transaction
from projectzero.ops.db_check import MIGRATIONS, _scratch_sql

pytestmark = pytest.mark.hosted
GOLDEN: dict[str, Any] = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_content.json").read_text(encoding="utf-8")
)
FILES = sorted(MIGRATIONS.glob("*.sql"))
M11 = next(p for p in FILES if "content_items" in p.name)


class Clock:
    def __init__(self) -> None:
        self.now = datetime.fromisoformat(GOLDEN["provenance"]["clock"])

    def __call__(self) -> datetime:
        return self.now


@pytest.fixture(scope="module")
def settings() -> Settings:
    try:
        return Settings.from_env()
    except RuntimeError as exc:
        pytest.skip(str(exc))


def _scratch(settings: Settings, sql: str) -> Iterator[str]:
    name = f"pz_itest_{secrets.token_hex(4)}"
    admin = connect(settings.db_url, autocommit=True)
    try:
        admin.execute(re.sub(r"\bpz\b", name, sql).encode() if "pz." in sql else sql.encode())
        yield name
    finally:
        admin.execute(f"drop schema if exists {name} cascade".encode())
        admin.close()


@pytest.fixture
def schema(settings: Settings) -> Iterator[str]:
    yield from _scratch(settings, _scratch_sql("pz"))


def seed(settings: Settings, schema: str, body: Any = None) -> int:
    """The archived ``content.json`` as the import writes it, then the shared mapping."""
    with transaction(settings.db_url) as conn:
        conn.execute(f"insert into {schema}.documents (key, body) values ('content.json', %s)".encode(),
                     (Jsonb(GOLDEN["seed"] if body is None else body),))  # fmt: skip
        row = conn.execute(f"select {schema}.backfill_content_items()".encode()).fetchone()
    assert row is not None
    return int(row[0])


@pytest.fixture
def api(settings: Settings, schema: str) -> Iterator[tuple[TestClient, Clock]]:
    app = create_app(Settings(db_url=settings.db_url, schema=schema))
    clock = Clock()
    app.state.clock = clock
    with TestClient(app, base_url="http://127.0.0.1:8177") as client:
        yield client, clock


def events(settings: Settings, schema: str) -> list[tuple[str, str, Any]]:
    with transaction(settings.db_url) as conn:
        rows = conn.execute(f"select item_id, action, detail from {schema}.content_item_events order by id".encode())
        return [(r[0], r[1], r[2]) for r in rows.fetchall()]


def test_the_old_script_replays_identically(settings: Settings, schema: str, api: tuple[TestClient, Clock]) -> None:
    client, clock = api
    assert seed(settings, schema) == 2
    assert client.get("/api/content").json() == GOLDEN["seed"]
    for i, (step, old) in enumerate(zip(GOLDEN["script"], GOLDEN["expected"], strict=True)):
        clock.now = datetime.fromisoformat(step["at"])
        r = client.post(f"/api/content/{step['op']}", json=step["body"])
        assert (r.status_code, r.json()) == (old["code"], old["body"]), f"step {i}"
        assert client.get("/api/content").json() == old["view"], f"step {i} view"
    actions = [a for _, a, _ in events(settings, schema)]
    # 5 creates (2 generated, own id, empty body, falsy id) + 1 recreate; 4 changing edits (steps 2, 3, 4, 9; step 5
    # changes nothing); 2 deletes (the repeated, the unknown and the empty one write nothing)
    assert (actions.count("create"), actions.count("save"), actions.count("delete")) == (6, 4, 2)


def test_the_upgrade_from_an_import_before_0011(settings: Settings) -> None:
    before = "\n".join(p.read_text(encoding="utf-8") for p in FILES if p < M11)
    for name in _scratch(settings, re.sub(r"\bpz\b", "pz", before)):
        with transaction(settings.db_url) as conn:
            conn.execute(f"insert into {name}.documents (key, body) values ('content.json', %s)".encode(),
                         (Jsonb(GOLDEN["seed"]),))  # fmt: skip
        with connect(settings.db_url, autocommit=True) as admin:
            admin.execute(re.sub(r"\bpz\b", name, M11.read_text(encoding="utf-8")).encode())
        app = create_app(Settings(db_url=settings.db_url, schema=name))
        app.state.clock = Clock()
        with TestClient(app, base_url="http://127.0.0.1:8177") as client:
            assert client.get("/api/content").json() == GOLDEN["seed"]  # the whole old GET, extra key included
            client.post("/api/content/save", json={"id": "c-261020080000", "title": "Edited after the upgrade"})
            with transaction(settings.db_url) as conn:
                again = conn.execute(f"select {name}.backfill_content_items()".encode()).fetchone()
            assert again == (0,)
            body = client.get("/api/content").json()
        assert body["note"] == GOLDEN["seed"]["note"]
        assert [i["id"] for i in body["items"]] == ["c-261101090000", "c-261020080000"]
        assert body["items"][1]["title"] == "Edited after the upgrade"


def test_repeated_unknown_and_unchanged_writes_add_no_event(
    settings: Settings, schema: str, api: tuple[TestClient, Clock]
) -> None:
    client, _ = api
    seed(settings, schema)
    client.post("/api/content/save", json={"id": "c-261101090000", "title": "Seeded draft"})  # unchanged
    for body in ({"id": "c-261101090000"}, {"id": "c-261101090000"}, {"id": "nope"}, {}, {"id": ""}):
        assert client.post("/api/content/delete", json=body).json() == {"ok": True}
    for bad in (0, False, None, 7, ["c-261020080000"]):  # Codex H-149: a present non-string id is refused
        r = client.post("/api/content/delete", json={"id": bad})
        assert (r.status_code, r.json()) == (400, {"ok": False, "error": "id must be a string"})
    assert events(settings, schema) == [("c-261101090000", "delete", {})]


def test_a_deleted_id_named_again_starts_fresh_on_top_with_its_history(
    settings: Settings, schema: str, api: tuple[TestClient, Clock]
) -> None:
    client, _ = api
    seed(settings, schema)
    client.post("/api/content/save", json={"id": "c-261020080000", "notes": "before"})
    client.post("/api/content/delete", json={"id": "c-261020080000"})
    r = client.post("/api/content/save", json={"id": "c-261020080000", "title": "Fresh"})
    assert r.json() == {"ok": True, "id": "c-261020080000"}
    items = client.get("/api/content").json()["items"]
    assert items[0] == {"id": "c-261020080000", "created": "2026-11-11", "title": "Fresh"}  # fresh fields only
    assert [i["id"] for i in items] == ["c-261020080000", "c-261101090000"]
    assert [(a, d) for i, a, d in events(settings, schema) if i == "c-261020080000"] == [
        ("save", {}), ("delete", {}), ("create", {"replaces_deleted": True})]  # fmt: skip


def test_new_items_in_the_same_second_get_distinct_ids(
    settings: Settings, schema: str, api: tuple[TestClient, Clock]
) -> None:
    client, _ = api
    first = client.post("/api/content/save", json={"title": "One"}).json()["id"]
    second = client.post("/api/content/save", json={"title": "Two"}).json()["id"]
    assert (first, second) == ("c-261111120000", "c-261111120000-2")  # the old code overwrote "One"
    ids: list[str] = []
    threads = [threading.Thread(target=lambda: ids.append(client.post("/api/content/save", json={"title": "C"}).json()["id"]))
               for _ in range(2)]  # fmt: skip
    for t in threads:
        t.start()
    for t in threads:
        t.join(60)
    assert sorted(ids) == ["c-261111120000-3", "c-261111120000-4"]
    assert [i["title"] for i in client.get("/api/content").json()["items"]] == ["C", "C", "Two", "One"]


def test_only_string_ids_are_accepted(settings: Settings, schema: str, api: tuple[TestClient, Clock]) -> None:
    client, _ = api
    old = GOLDEN["numeric"]["expected"][0]["view"]["items"][0]["id"]
    assert old == 7  # the old app stored the number as sent
    for body in ({"id": 7, "title": "A number id"}, {"id": True}, {"id": ["x"]}, {"id": {"a": 1}}):
        r = client.post("/api/content/save", json=body)
        assert (r.status_code, r.json()) == (400, {"ok": False, "error": "id must be a string"})
    assert client.post("/api/content/delete", json={"id": 7}).status_code == 400
    assert client.post("/api/content/save", json={"id": "7", "title": "A string id"}).json() == {"ok": True, "id": "7"}
    assert [i["id"] for i in client.get("/api/content").json()["items"]] == ["7"]
    assert [a for _, a, _ in events(settings, schema)] == ["create"]
